/* 앱 시작 시 Firebase 초기화 */
/* A failed listener is terminal. Retry only on foreground/network events. */
function _resumeFirestoreListener(){
  if(document.visibilityState==='hidden'||navigator.onLine===false)return;
  if(!hasAdminSession()||_fbUnsub)return;
  try{_startFirestoreListener();}catch(e){
    console.error('Firestore 재연결 오류',e);
    _showSyncStatus('⚠️ 재연결 실패');
  }
}
window.addEventListener('online',_resumeFirestoreListener);
document.addEventListener('visibilitychange',_resumeFirestoreListener);

